(() => {
'use strict';
const items=[["DRC", "物理正确性", "这些金属形状能按工艺制造吗？", "检查线宽、间距、金属图形最小面积、过孔包围等。这里的最小面积是局部图形规则，芯片总面积则属于规格预算。", "physical/drc"], ["LVS", "版图与网表一致性", "版图实际接出的电路对吗？", "从版图提取器件与连接，对比最终参考网表，定位开路、短路或器件不匹配。LVS 通过不代表网表逻辑本身正确。", "lvs/lvs"], ["LEC", "逻辑等价性", "后端改完网表，逻辑行为变了吗？", "插 BUF、换驱动、重构逻辑或插反相器对后，与批准的参考设计比较逻辑行为。它和 LVS 检查不同的关系。", "lvs/buffers"], ["STA", "时序分析", "信号既不晚到，也不过早变化吗？", "结合单元延迟、走线寄生 RC、时钟与约束，检查 setup、hold 及其他适用项目；覆盖规定的模式与角点。", "timing/sta"], ["SI", "信号完整性", "邻线切换会影响这条信号吗？", "检查耦合引起的串扰延迟变化和噪声；考虑这些影响后，时序和噪声仍应满足要求。", "constraints/si"], ["DENSITY / FILL", "局部密度与填充", "局部图形密度符合工艺要求吗？", "检查规定窗口的密度，必要时补金属填充；填充可能改变耦合电容，需要纳入最终物理检查和寄生/时序复查。", "physical/density"], ["IR DROP / EM", "供电与长期可靠性", "电压送到各处够吗，金属能长期承载吗？", "IR drop 检查静态/动态压降和局部电压；EM 检查金属及过孔的电流承载可靠性。两者使用各自的预算与模型。", "power/ir"], ["POWER", "功耗预算", "芯片在规定负载下耗电多少？", "按工作模式、切换活动、电压与温度分析动态和漏电功耗，与项目预算比较。功耗分析与电气连接检查分别进行。", "power/power-budget"], ["ERC / PERC", "电气连接与规则", "电源地和器件接法符合电气要求吗？", "按适用规则检查供电连接、浮空节点、器件端电压与电压域接口等；几何合法、网表匹配仍可能留下电气风险。", "power/erc"], ["ESD", "静电保护", "静电脉冲有没有合适的泄放路径？", "核对保护结构、连通与放电路径，并按项目方法分析路径电阻、瞬态电流承载等。保护器件存在只是检查的一部分。", "power/esd"]];
window.SignoffCheckMap={render(base=''){return '<div class="signoff-check-map">'+items.map((x,i)=>'<a class="signoff-check-card" href="'+base+'#'+x[4]+'"><div><span>'+String(i+1).padStart(2,'0')+' / '+x[0]+'</span><b>↗</b></div><h3>'+x[1]+'</h3><strong>'+x[2]+'</strong><p>'+x[3]+'</p></a>').join('')+'</div>';}};
})();
